use std::collections::{BTreeSet, HashMap};
use std::fmt::Write;

use heck::{ToSnakeCase, ToUpperCamelCase};
use prost_reflect::{
    DescriptorPool, ExtensionDescriptor, FieldDescriptor, Kind, MessageDescriptor, Value,
};

const ID_EXTENSION: &str = "bolt.options.v1.id";
const HEADER: &str =
    "// @generated by protoc-gen-bolt from bolt.options.v1 options. DO NOT EDIT.\n";

/// Renders `bolt_ext.rs` for every message in `files` that carries `(bolt.options.v1.id)`.
pub fn generate(pool: &DescriptorPool, files: &[String]) -> Result<String, String> {
    let mut out = String::from(HEADER);
    let Some(id_ext) = pool.get_extension_by_name(ID_EXTENSION) else {
        return Ok(out);
    };
    let files: BTreeSet<&str> = files.iter().map(String::as_str).collect();

    let mut errors = Vec::new();
    for message in pool.all_messages() {
        if !files.contains(message.parent_file().name()) || message.is_map_entry() {
            continue;
        }
        let Some(paths) = id_paths(&message, &id_ext) else {
            continue;
        };
        match render_id(&message, &paths) {
            Ok(code) => out.push_str(&code),
            Err(e) => errors.push(format!(
                "{}: {}: {e}",
                message.parent_file().name(),
                message.full_name()
            )),
        }
    }

    if errors.is_empty() {
        Ok(out)
    } else {
        Err(errors.join("\n"))
    }
}

fn id_paths(message: &MessageDescriptor, id_ext: &ExtensionDescriptor) -> Option<Vec<String>> {
    let options = message.options();
    if !options.has_extension(id_ext) {
        return None;
    }
    let Value::Message(spec) = options.get_extension(id_ext).into_owned() else {
        return None;
    };
    let paths = match spec.get_field_by_name("fields").as_deref() {
        Some(Value::List(values)) => values
            .iter()
            .filter_map(|v| v.as_str().map(str::to_owned))
            .collect(),
        _ => Vec::new(),
    };
    Some(paths)
}

fn render_id(message: &MessageDescriptor, paths: &[String]) -> Result<String, String> {
    if paths.is_empty() {
        return Err("(bolt.options.v1.id) needs at least one field path".to_owned());
    }
    if let Some(field) = message
        .fields()
        .find(|f| field_ident(f) == "id" && has_prost_getter(f))
    {
        return Err(format!(
            "field `{}` already gets a prost-generated `id()` getter, which collides with the generated `id()`",
            field.name()
        ));
    }

    let mut body = Body::default();
    let mut types = Vec::with_capacity(paths.len());
    let mut exprs = Vec::with_capacity(paths.len());
    for path in paths {
        let (ty, expr) = body
            .resolve(message, path)
            .map_err(|e| format!("id path `{path}`: {e}"))?;
        types.push(ty);
        exprs.push(expr);
    }

    let (ty, expr) = if paths.len() == 1 {
        (types.remove(0), exprs.remove(0))
    } else {
        (
            format!("({})", types.join(", ")),
            format!("({})", exprs.join(", ")),
        )
    };
    let (ty, expr) = if body.fallible {
        (
            format!("::core::option::Option<{ty}>"),
            format!("Some({expr})"),
        )
    } else {
        (ty, expr)
    };

    let documented = paths
        .iter()
        .map(|p| format!("`{p}`"))
        .collect::<Vec<_>>()
        .join(", ");
    let mut code = String::new();
    writeln!(code, "\nimpl {} {{", rust_path(message)).unwrap();
    writeln!(
        code,
        "    /// Composite id from `(bolt.options.v1.id)`: {documented}."
    )
    .unwrap();
    if body.fallible {
        writeln!(
            code,
            "    /// `None` when a message field on the path is unset."
        )
        .unwrap();
    }
    writeln!(code, "    pub fn id(&self) -> {ty} {{").unwrap();
    for line in &body.lets {
        writeln!(code, "        {line}").unwrap();
    }
    writeln!(code, "        {expr}").unwrap();
    writeln!(code, "    }}\n}}").unwrap();
    Ok(code)
}

/// Accumulates the `let` bindings shared by every path of one id, so a message field
/// used by several paths (`instrument.base`, `instrument.quote`) is unwrapped once.
#[derive(Default)]
struct Body {
    lets: Vec<String>,
    bindings: HashMap<String, String>,
    fallible: bool,
}

impl Body {
    /// Returns the Rust type and expression of one dotted field path.
    fn resolve(
        &mut self,
        root: &MessageDescriptor,
        path: &str,
    ) -> Result<(String, String), String> {
        let segments: Vec<&str> = path.split('.').collect();
        let (leaf, hops) = segments
            .split_last()
            .expect("split yields at least one segment");

        let mut message = root.clone();
        let mut expr = "self".to_owned();
        for (depth, segment) in hops.iter().enumerate() {
            let field = lookup(&message, segment)?;
            let Kind::Message(next) = field.kind() else {
                return Err(format!(
                    "`{segment}` is not a message field, so the path can't go through it"
                ));
            };
            let prefix = segments[..=depth].join(".");
            expr = match self.bindings.get(&prefix) {
                Some(var) => var.clone(),
                None => {
                    let var = format!("m{}", self.bindings.len());
                    self.lets.push(format!(
                        "let {var} = {expr}.{}.as_ref()?;",
                        field_ident(&field)
                    ));
                    self.bindings.insert(prefix, var.clone());
                    self.fallible = true;
                    var
                }
            };
            message = next;
        }

        let field = lookup(&message, leaf)?;
        let access = format!("{expr}.{}", field_ident(&field));
        let optional = field.supports_presence();
        let (ty, expr) = match field.kind() {
            Kind::String if optional => ("&str".to_owned(), format!("{access}.as_deref()?")),
            Kind::String => ("&str".to_owned(), format!("{access}.as_str()")),
            Kind::Bytes if optional => ("&[u8]".to_owned(), format!("{access}.as_deref()?")),
            Kind::Bytes => ("&[u8]".to_owned(), format!("&{access}[..]")),
            Kind::Message(_) | Kind::Enum(_) => {
                return Err(format!(
                    "`{leaf}` must be a scalar field (string, bytes, integer, bool or float)"
                ));
            }
            scalar => {
                let ty = scalar_type(&scalar).to_owned();
                (
                    ty,
                    if optional {
                        format!("{access}?")
                    } else {
                        access
                    },
                )
            }
        };
        self.fallible |= optional;
        Ok((ty, expr))
    }
}

fn lookup(message: &MessageDescriptor, name: &str) -> Result<FieldDescriptor, String> {
    let field = message
        .get_field_by_name(name)
        .ok_or_else(|| format!("`{}` has no field `{name}`", message.full_name()))?;
    if field.is_list() || field.is_map() {
        return Err(format!(
            "`{name}` is repeated or a map; an id needs a single value"
        ));
    }
    if field
        .containing_oneof()
        .is_some_and(|oneof| !oneof.is_synthetic())
    {
        return Err(format!(
            "`{name}` is in a oneof, which prost models as an enum"
        ));
    }
    Ok(field)
}

fn scalar_type(kind: &Kind) -> &'static str {
    match kind {
        Kind::Double => "f64",
        Kind::Float => "f32",
        Kind::Int32 | Kind::Sint32 | Kind::Sfixed32 => "i32",
        Kind::Int64 | Kind::Sint64 | Kind::Sfixed64 => "i64",
        Kind::Uint32 | Kind::Fixed32 => "u32",
        Kind::Uint64 | Kind::Fixed64 => "u64",
        Kind::Bool => "bool",
        Kind::String | Kind::Bytes | Kind::Message(_) | Kind::Enum(_) => {
            unreachable!("handled by the caller")
        }
    }
}

/// prost generates an accessor method named after the field for enums and
/// presence-tracked scalars.
fn has_prost_getter(field: &FieldDescriptor) -> bool {
    if field.is_list() || field.is_map() {
        return false;
    }
    match field.kind() {
        Kind::Enum(_) => true,
        Kind::Message(_) => false,
        _ => {
            field.supports_presence()
                && field
                    .containing_oneof()
                    .is_none_or(|oneof| oneof.is_synthetic())
        }
    }
}

/// `crate::` path of the prost type, mirroring prost's module layout.
fn rust_path(message: &MessageDescriptor) -> String {
    let mut segments: Vec<String> = message
        .package_name()
        .split('.')
        .map(module_ident)
        .collect();
    let mut parents = Vec::new();
    let mut parent = message.parent_message();
    while let Some(p) = parent {
        parents.push(module_ident(p.name()));
        parent = p.parent_message();
    }
    segments.extend(parents.into_iter().rev());
    segments.push(type_ident(message.name()));
    format!("crate::{}", segments.join("::"))
}

fn type_ident(name: &str) -> String {
    let ident = name.to_upper_camel_case();
    if ident == "Self" {
        ident + "_"
    } else {
        ident
    }
}

fn field_ident(field: &FieldDescriptor) -> String {
    module_ident(field.name())
}

/// prost's `to_snake`: raw identifiers for keywords, a `_` suffix for the ones that can't be raw.
fn module_ident(name: &str) -> String {
    let ident = name.to_snake_case();
    match ident.as_str() {
        "crate" | "self" | "super" | "Self" | "extern" => ident + "_",
        "as" | "async" | "await" | "break" | "const" | "continue" | "dyn" | "else" | "enum"
        | "false" | "fn" | "for" | "if" | "impl" | "in" | "let" | "loop" | "match" | "mod"
        | "move" | "mut" | "pub" | "ref" | "return" | "static" | "struct" | "trait" | "true"
        | "type" | "unsafe" | "use" | "where" | "while" | "abstract" | "become" | "box" | "do"
        | "final" | "gen" | "macro" | "override" | "priv" | "try" | "typeof" | "unsized"
        | "virtual" | "yield" => format!("r#{ident}"),
        _ => ident,
    }
}

